@if (isset($clock))<section class="rounded border p-4"><h2 class="text-lg font-semibold">受理响应时钟</h2><p>{{ $clock['notice'] }}</p>@if (isset($clock['due_at']))<p>首次联系截止：{{ $clock['due_at'] }} UTC · 日历 {{ $clock['calendar_version'] }} · {{ $clock['timezone'] }} · {{ $clock['status'] }}</p>@endif</section>@endif
@if (bouncer()->hasPermission('catalog.scene-workflow.preserve') || bouncer()->hasPermission('catalog.scene-workflow.preserve_read'))<section class="rounded border p-4"><h2 class="text-lg font-semibold">私有资料保全</h2><p>到期资料不能从普通下载入口读取；保全仅阻止清理，不延长普通访问权限。解除须由另一人执行。撤销不删除原件。</p>
@forelse ($attachmentRecords??[] as $file)<details class="mt-3 border-t pt-3"><summary>附件 #{{ $file->id }} · {{ $file->state }} · {{ $file->revoked_at?'已撤销':'未撤销' }} · 到期 {{ $file->expires_at }} UTC</summary>
@if (bouncer()->hasPermission('catalog.scene-workflow.preserve') && !in_array($file->state,['deleted','deletion_pending']))<form method="POST" action="{{ route('admin.catalog.scene-workflow.attachment-action',['id'=>$record->id,'attachmentId'=>$file->id,'action'=>'hold']) }}" class="mt-3">@csrf<label>保全依据/工单编号<input name="reference" maxlength="255" required></label><label>保全原因<input name="reason" minlength="3" maxlength="5000" required></label><button class="secondary-button">申请保全原件</button></form>@endif
@if (bouncer()->hasPermission('catalog.scene-workflow.preserve_read') && ($holds??collect())->where('attachment_id',$file->id)->whereNull('released_at')->isNotEmpty())<form method="POST" action="{{ route('admin.catalog.scene-workflow.preserved-attachment',['id'=>$record->id,'attachmentId'=>$file->id]) }}" class="mt-3">@csrf<label>本次必要保全读取用途<input name="reason" minlength="3" maxlength="2000" required></label><button class="secondary-button">留痕后读取保全原件</button></form>@endif
@foreach (($holds??collect())->where('attachment_id',$file->id) as $hold)<p>#{{ $hold->id }} · {{ $hold->reference }} · {{ $hold->reason }} · {{ $hold->released_at?'已解除':'保全中' }}</p>@if (!$hold->released_at && bouncer()->hasPermission('catalog.scene-workflow.preserve'))<form method="POST" action="{{ route('admin.catalog.scene-workflow.attachment-action',['id'=>$record->id,'attachmentId'=>$file->id,'action'=>'release']) }}" class="mt-2">@csrf<input type="hidden" name="hold_id" value="{{ $hold->id }}"><label>解除依据<input name="reason" minlength="3" maxlength="5000" required></label><button class="secondary-button">独立解除此项保全</button></form>@endif @endforeach
@if (bouncer()->hasPermission('catalog.scene-workflow.preserve') && !$file->revoked_at && $file->state!=='deleted')<form method="POST" action="{{ route('admin.catalog.scene-workflow.attachment-action',['id'=>$record->id,'attachmentId'=>$file->id,'action'=>'revoke']) }}" class="mt-3">@csrf<label>撤销依据<input name="reason" minlength="3" maxlength="5000" required></label><button class="secondary-button">撤销资料使用资格</button></form>@endif</details>@empty<p>暂无资料。</p>@endforelse</section>@endif
